style.css:
/* Hide default YouTube logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Sonic nunchucks GIF with hover bounce */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/9rELp2-Tm7kAAAAi/sonic-the-hedgehog-nunchucks.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
  transition: transform 0.2s ease;
}

ytd-topbar-logo-renderer:hover {
  animation: sonicBounce 0.4s infinite alternate;
}

@keyframes sonicBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-4px); }
}
